using System;using System.IO;using System.Diagnostics;using Microsoft.Win32;
namespace FileCompass {
 public static partial class FileViewers {
  internal static ProcessStartInfo NotepadEditInfo(string file){return new ProcessStartInfo(Path.Combine(Environment.SystemDirectory,"notepad.exe"),SshTerminal.QuoteWindowsArgument(Path.GetFullPath(file))){UseShellExecute=true};}
  internal static string FindExcel(){foreach(var hive in new[]{RegistryHive.CurrentUser,RegistryHive.LocalMachine})foreach(var view in new[]{RegistryView.Registry64,RegistryView.Registry32})try{using(var root=RegistryKey.OpenBaseKey(hive,view))using(var key=root.OpenSubKey(@"Software\Microsoft\Windows\CurrentVersion\App Paths\excel.exe")){string path=key==null?null:key.GetValue(null) as string;if(!String.IsNullOrWhiteSpace(path)){path=Environment.ExpandEnvironmentVariables(path.Trim().Trim('"'));if(File.Exists(path))return path;}}}catch(System.Security.SecurityException){}catch(UnauthorizedAccessException){}string associated=QueryAssociation(".xlsx",2,"open");if(!String.IsNullOrWhiteSpace(associated)&&String.Equals(Path.GetFileName(associated.Trim('"')),"EXCEL.EXE",StringComparison.OrdinalIgnoreCase)&&File.Exists(associated.Trim('"')))return associated.Trim('"');foreach(string folder in new[]{Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86)})foreach(string relative in new[]{@"Microsoft Office\root\Office16\EXCEL.EXE",@"Microsoft Office\Office16\EXCEL.EXE",@"Microsoft Office\Office15\EXCEL.EXE",@"Microsoft Office\Office14\EXCEL.EXE"}){string path=Path.Combine(folder,relative);if(File.Exists(path))return path;}return null;}
  internal static ProcessStartInfo ExcelEditInfo(string file,Func<string> resolve=null){string program=(resolve??FindExcel)();if(String.IsNullOrWhiteSpace(program)||!File.Exists(program))throw new IOException(L.Text("editor.excelMissing"));return new ProcessStartInfo(program,SshTerminal.QuoteWindowsArgument(Path.GetFullPath(file))){UseShellExecute=true};}
 }
}
